# The enclosed square's interior side length determines its fill color.
FILL_COLOR_BY_SIDE = {3: 8, 5: 4, 7: 3}


def transform(grid):
    """Fill each 2-bounded enclosed region using its interior side-size color."""
    h, w = len(grid), len(grid[0])
    exterior = set()
    queue = deque()

    # Zeros connected to the outside, including diagonally, remain unchanged.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 and (r == 0 or r == h - 1 or c == 0 or c == w - 1):
                exterior.add((r, c))
                queue.append((r, c))
    while queue:
        r, c = queue.popleft()
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                nr, nc = r + dr, c + dc
                if (dr or dc) and 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and (nr, nc) not in exterior:
                    exterior.add((nr, nc))
                    queue.append((nr, nc))

    out = [row[:] for row in grid]
    seen = set(exterior)
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            cells = {(r, c)}
            seen.add((r, c))
            queue.append((r, c))
            while queue:
                x, y = queue.popleft()
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        nx, ny = x + dr, y + dc
                        if (dr or dc) and 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 0 and (nx, ny) not in seen:
                            seen.add((nx, ny))
                            cells.add((nx, ny))
                            queue.append((nx, ny))

            rows = [x for x, _ in cells]
            cols = [y for _, y in cells]
            side = max(max(rows) - min(rows) + 1, max(cols) - min(cols) + 1)
            color = FILL_COLOR_BY_SIDE.get(side)
            if color is not None:
                for x, y in cells:
                    out[x][y] = color
    return out
